<script>
function end_timers123() {
    // Local storage check: अगर पहले से future date सेट है, तो उसे इस्तेमाल करो
    let future = localStorage.getItem("futureTime");

    // अगर future टाइम नहीं है या अब से पुराना हो चुका है, तो नया सेट करो (2 दिन बाद)
    if (!future || new Date().getTime() > future) {
        future = new Date().getTime() + (2 * 24 * 60 * 60 * 1000); // अभी से 2 दिन बाद का टाइम
        localStorage.setItem("futureTime", future); // Future time को save करो
    }

    function updateCountdown122() {
        let now = new Date().getTime();
        let diff = future - now;

        // अगर टाइम 0 हो गया तो 2 दिन आगे रीसेट करो
        if (diff <= 0) {
            future = new Date().getTime() + (2 * 24 * 60 * 60 * 1000);
            localStorage.setItem("futureTime", future);
            diff = future - now;
        }

        let days = Math.floor(diff / (1000 * 60 * 60 * 24));
        let hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
        let mins = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
        let secs = Math.floor((diff % (1000 * 60)) / 1000);

        document.getElementById("end_timers123").innerHTML =
            `<div>${days}d <span>: </span></div>
             <div>${hours}h <span>: </span></div>
             <div>${mins}m <span>: </span></div>
             <div>${secs}s</div>`;
    }

    // हर सेकंड में अपडेट करें
    setInterval(updateCountdown122, 1000);
    updateCountdown122(); // Page load होने पर तुरंत रन करें
}

// Countdown शुरू करें
end_timers123();
</script>
