$(document).ready(function () {
    // Event listener for clicks on video cards
    $('.overlap').on('click', function () {
        // Get data attributes from the clicked video
        const videoLink = $(this).data('video-link');
        const videoHeading = $(this).data('heading');

        // Dynamically set the content in the modal
        $('#dynamic_video_iframe').attr('src', videoLink);
        $('#dynamic_video_heading').text(videoHeading);

        // Open the modal
        $('#dynamic_video_modal').modal('show');
    });

    // Clear the iframe source when modal is closed
    $('#dynamic_video_modal').on('hidden.bs.modal', function () {
        $('#dynamic_video_iframe').attr('src', '');
    });
});



document.addEventListener('DOMContentLoaded', function () {
  // Select all play buttons
  const playButtons = document.querySelectorAll('.play-video-button');

  playButtons.forEach(button => {
    button.addEventListener('click', function () {
      // Get the video link from data attribute
      const videoLink = this.getAttribute('data-video');
      // Set the iframe src to the video link
      const iframe = document.getElementById('video-iframe');
      iframe.src = videoLink;
    });
  });

  // Clear iframe src when modal is closed
  document.getElementById('you_tUbe_close').addEventListener('click', function () {
    const iframe = document.getElementById('video-iframe');
    iframe.src = ''; // Clear src to stop video playback
  });
}); 

















document.addEventListener("DOMContentLoaded", function () {
  // Select all panel headings
  const panelHeadings = document.querySelectorAll(".panel-heading");

  panelHeadings.forEach((heading) => {
    heading.addEventListener("click", function () {
      const parentPanel = this.parentElement;

      // Check if the clicked panel is already active
      if (parentPanel.classList.contains("active")) {
        // If active, remove 'active' class
        parentPanel.classList.remove("active");
      } else {
        // If not active, remove 'active' from all panels
        document.querySelectorAll(".panel-default").forEach((panel) => {
          panel.classList.remove("active");
        });

        // Add 'active' class to the clicked panel's parent
        parentPanel.classList.add("active");
      }
    });
  });
});





</script>
<script>
    $(document).ready(function () {
        function cleanText(text) {
            return text.replace(/\s+/g, ' ').trim(); // Multiple spaces ko ek space me convert karega
        }

        function updateInputField() {
            var selectedRadio = $("input[type='radio'][name='batch']:checked");

            if (selectedRadio.length > 0) {
                var cdate = cleanText(selectedRadio.closest('.radio-inline').find('.batchtable_date__2AO60').text());
                var ragularname = cleanText(selectedRadio.closest('.radio-inline').find(".batchtable_dayweek__32_nM").attr("ragularname"));

                // Check if related checkbox is checked
                var relatedCheckbox = selectedRadio.closest('.radio-inline').find("input[type='checkbox']");
                var fasttrack = relatedCheckbox.is(":checked") ? " / " + cleanText(relatedCheckbox.attr("fasttrack")) : "";

                $("#batchInput").val(cdate + " / " + ragularname + fasttrack);
                
              //  $("#enrollbatchpopup_date__XJedo").html(cdate);
            }
        }

        // Initial check on page load
        updateInputField();

        // Radio button click event
        $("input[type='radio'][name='batch']").click(updateInputField);

        // Checkbox change event
        $("input[type='checkbox']").change(function () {
            var relatedRadio = $(this).closest('.radio-inline').find("input[type='radio'][name='batch']");

            if (relatedRadio.is(":checked")) {
                // If the checkbox belongs to the selected radio button, update input field
                updateInputField();
            }
        });
    });
</script>


